// How many to publish per run. Start at 2 and raise it once you have
// watched a few land — five same-day uploads compete with each other.
const PER_RUN = 5;

// Which files have already gone out. Stored on the workflow itself, so it
// survives restarts and this node is the single source of truth for
// "what is next". Clearing it will re-post everything.
const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.posted)) store.posted = [];

const queue = $input.first().json.videos || [];
if (!queue.length) throw new Error('queue is empty — did the GitHub fetch fail?');

const next = queue
  .filter(v => !store.posted.includes(v.file))
  .slice(0, PER_RUN);

if (!next.length) return [];   // everything has been posted; nothing to do

// Mark them before sending. Posting is not reversible, so the failure we
// guard against is a DUPLICATE upload, not a missed one — a video that
// silently fails can be re-queued by hand, a double upload cannot be undone.
for (const v of next) store.posted.push(v.file);

return next.map(v => ({
  json: {
    video_url: v.url,
    title: v.title,
    description: (v.description || '').slice(0, 4900),
    tags: v.tags || []
  }
}));
